@'
import fs from 'node:fs';
let count=0,found=[];for(const folder of ['docs','skills','.agents','.claude']){if(!fs.existsSync(folder))continue;const walk=d=>{for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=d+'/'+e.name;if(e.isDirectory())walk(p);else if(e.name.endsWith('.md')){count++;if(fs.readFileSync(p,'utf8').includes('\u2014'))found.push(p);}}};walk(folder);}for(const p of ['README.md','CONTRIBUTING.md','QA_REPORT.md','AGENTS.md','CLAUDE.md']){count++;if(fs.readFileSync(p,'utf8').includes('\u2014'))found.push(p);}console.log(JSON.stringify({count,emDashes:found}));
'@ | node --input-type=module
